  核心词库 = {
    "用户": "龍",      # 龙：权威/身份
    "指纹": "紋",      # 纹：唯一标记
    "同意": "心",      # 心：意愿/同意
    "状态": "態",      # 态：状态
    "隐私": "密",      # 密：秘密
    "等级": "級",      # 级：等级
    "审计": "審",      # 审：审查
    "拦截": "攔",      # 拦：阻拦
    "通知": "知",      # 知：告知
    "发布": "發",      # 发：发布
  }

  # 生成混淆变量名
  函数 生成混淆名(原始变量名) {
    步骤1 = 提取核心词(原始变量名)  # "用户指纹" → ["用户", "指纹"]
    步骤2 = 映射到简体字(步骤1)      # ["龍", "紋"]
    步骤3 = 生成随机哈希(4位)        # "a8f3"

    返回 步骤2[0] + "_" + 步骤3      # "龍_a8f3"
  }

  # 防碰撞检查
  函数 检查唯一性(混淆名, 已用列表) {
    如果 (混淆名 在 已用列表中) {
      返回 生成混淆名(原始变量名)  # 重新生成
    }
    返回 混淆名
  }
}
